package com.wandertrace.dto;
import jakarta.validation.constraints.*;import java.time.*;import java.util.*;
public final class ContentDtos {private ContentDtos(){} public record DestinationRequest(@NotBlank @Size(max=255) String name,@Size(max=255) String city,@NotBlank @Size(max=255) String country,@DecimalMin("-90") @DecimalMax("90") Double latitude,@DecimalMin("-180") @DecimalMax("180") Double longitude,@Size(max=5000) String description,String coverImageUrl){} public record Destination(UUID id,UUID tripId,String name,String city,String country,Double latitude,Double longitude,String description,String coverImageUrl,Instant createdAt,Instant updatedAt){} public record MemoryRequest(@NotBlank @Size(max=255) String title,@Size(max=1000) String subtitle,@NotBlank @Size(max=30000) String story,@NotNull LocalDate memoryDate,@Pattern(regexp="PUBLIC|PRIVATE") String visibility,UUID coverMediaId){} public record Memory(UUID id,UUID destinationId,String title,String subtitle,String story,LocalDate memoryDate,String visibility,UUID coverMediaId,Instant createdAt,Instant updatedAt){} public record Media(UUID id,UUID memoryId,String type,String storageKey,String url,String thumbnailUrl,String title,String caption,String mimeType,long fileSize,int sortOrder,Instant createdAt){} public record MediaMetadata(@Size(max=255) String title,@Size(max=2000) String caption,@Min(0) Integer sortOrder,Boolean cover){} }
